    #[test]
    fn ppp_extrapolation_and_real_adjustment() {
        // PPP 3.4 in 2023; home prices +10%, US prices +5% since: 3.4 * 1.10 / 1.05
        assert!((ppp_today(3.4, 100.0, 110.0, 200.0, 210.0) - 3.4 * 1.10 / 1.05).abs() < 1e-12);
        // a year-ago rate of 7.0 with 4% home and 2% US inflation over the year is worth 7.0 * 1.04 / 1.02 today
        assert!((real_adjust(7.0, 100.0, 104.0, 100.0, 102.0) - 7.0 * 1.04 / 1.02).abs() < 1e-12);
        assert!((pct(3.4, 6.8) + 50.0).abs() < 1e-12);
        let fx: Vec<(String, f64)> = vec![("2025-10-01".into(), 7.0), ("2025-10-30".into(), 7.2), ("2026-10-01".into(), 6.9), ("2026-10-30".into(), 7.1)];
        let end = NaiveDate::from_ymd_opt(2026, 10, 30).unwrap();
        assert_eq!(window_avg(&fx, end, 30), Some(7.0));
        assert_eq!(window_avg(&fx, end - Days::days(365), 30), Some(7.1));
        let y = |v: &[(i32, f64)]| v.iter().map(|(a, b)| (a.to_string(), *b)).collect::<Vec<_>>();
        let r = fx_ppp_row(&json!({"cc":"CN","ccy":"CNY","label":"Chinese yuan","group":"em"}), &fx, &y(&[(2024, 3.5), (2025, 3.4)]),
            &y(&[(2024, 100.0), (2025, 101.0), (2026, 103.0)]), &y(&[(2024, 140.0), (2025, 143.0)]), 30);
        // CPI year = 2025 (the US stops there); PPP base 2025, so no extrapolation: 3.4 vs spot 7.1
        assert_eq!(r["cpi_year"], json!(2025));
        assert!((r["over_under_pct"].as_f64().unwrap() - pct(3.4, 7.1)).abs() < 1e-12);
        let want_real = real_adjust(7.1, 100.0, 101.0, 140.0, 143.0);
        assert!((r["avg_window_year_ago_real"].as_f64().unwrap() - want_real).abs() < 1e-12);
        assert!((r["real_change_pct"].as_f64().unwrap() - pct(want_real, 7.0)).abs() < 1e-12);
        let e = fx_ppp_row(&json!({"cc":"SA","ccy":"SAR"}), &[], &[], &[], &[], 30);
        assert!(e["spot"].is_null() && e["null_reason"]["spot"].is_string() && e["null_reason"]["ppp"].is_string());
    }

    #[test]
    fn rba_f17_short_end_and_riksbank_5y_benchmarks() {
        // RBA F17 zero-coupon curve: the declared FZCY ids become AU 3M/6M/1Y/7Y; an undeclared column and a blank cell give nothing.
        let f17 = "F17 ZERO-COUPON\nTitle,Zero-coupon yield – 0.25 yrs,Zero-coupon yield – 0.5 yrs,Zero-coupon yield – 1 yr,Zero-coupon yield – 2 yrs,Zero-coupon yield – 7 yrs\nSeries ID,FZCY25D,FZCY50D,FZCY100D,FZCY200D,FZCY700D\n30-Sep-2026,3.61,3.58,3.52,3.40,\n";
        let d = json!({"header":"Series ID","date_fmt":"%d-%b-%Y","map":{"FZCY25D":"curve:AU:3M","FZCY50D":"curve:AU:6M","FZCY100D":"curve:AU:1Y","FZCY700D":"curve:AU:7Y"}});
        assert_eq!(csv_wide(f17, &d), vec![ob("curve:AU:3M", "2026-09-30".into(), 3.61), ob("curve:AU:6M", "2026-09-30".into(), 3.58), ob("curve:AU:1Y", "2026-09-30".into(), 3.52)]);
        // Riksbank group 99 (international 5Y): only the declared FR and NL series are kept.
        let r = riksbank(r#"[{"seriesId":"FRGVB5Y","date":"2026-10-30","value":2.81},{"seriesId":"DEGVB5Y","date":"2026-10-30","value":2.3},{"seriesId":"NLGVB5Y","date":"2026-10-30","value":2.55}]"#, &json!({"map":{"FRGVB5Y":"curve:FR:5Y","NLGVB5Y":"curve:NL:5Y"}}));
        assert_eq!(r, vec![ob("curve:FR:5Y", "2026-10-30".into(), 2.81), ob("curve:NL:5Y", "2026-10-30".into(), 2.55)]);
    }

    #[test]
    fn valet_dbnomics_worldbank_frankfurter() {
        let v = valet(r#"{"observations":[{"d":"2026-10-30","BD.CDN.10YR.DQ.YLD":{"v":"3.21"},"TB.CDN.90D.MID":{"v":""}}]}"#, &json!({"map":{"BD.CDN.10YR.DQ.YLD":"curve:CA:10Y","TB.CDN.90D.MID":"curve:CA:3M"}}));
        assert_eq!(v, vec![ob("curve:CA:10Y", "2026-10-30".into(), 3.21)]);
        let d = dbnomics(r#"{"series":{"docs":[{"series_code":"IND.M.IRLT.PA._Z._Z._Z","period":["2026-04","2026-05"],"value":["NA",7.02]}]}}"#, &json!({"map":{"IND.M.IRLT.PA._Z._Z._Z":"curve:IN:10Y"}}));
        assert_eq!(d, vec![ob("curve:IN:10Y", "2026-05".into(), 7.02)]);
        let r = riksbank(r#"[{"seriesId":"SEGVB10YC","date":"2026-10-30","value":3.142},{"seriesId":"SETB12MBENCH","date":"2010-10-06","value":0.73}]"#, &json!({"map":{"SEGVB10YC":"curve:SE:10Y"}}));
        assert_eq!(r, vec![ob("curve:SE:10Y", "2026-10-30".into(), 3.142)]);
        let w = worldbank(r#"[{"page":1},[{"country":{"id":"CN"},"date":"2025","value":1.9e13},{"country":{"id":"TW"},"date":"2025","value":null}]]"#);
        assert_eq!(w, vec![ob("gdp:CN", "2025".into(), 1.9e13)]);
        let mut f = frankfurter_ts(r#"{"rates":{"2026-10-29":{"BRL":5.4,"KRW":1400}}}"#);
        f.sort_by(|a, b| a.id.cmp(&b.id));
        assert_eq!(f[0], ob("fx:USDBRL", "2026-10-29".into(), 5.4));
    }

