    #[test]
    fn sec_reported_and_estimated() {
        let body = r#"{"name":"Apple Inc.","filings":{"recent":{"form":["8-K","10-Q","8-K","8-K","8-K"],
            "filingDate":["2026-10-30","2026-10-31","2026-07-31","2026-05-01","2026-02-12"],
            "items":["2.02,9.01","","2.02,9.01","2.02","5.02"],"accessionNumber":["0000320193-26-000101","x","a","b","c"],"primaryDocument":["d.htm","","e","f","g"]}}}"#;
        let day = NaiveDate::from_ymd_opt(2026, 10, 31).unwrap();
        let d = sec_earnings(body, "AAPL", "0000320193", "base/{cik}/{accession}/{document}", day, 120);
        let r = d["reported"].as_array().unwrap();
        assert_eq!(r.len(), 2);
        assert_eq!(r[0]["url"], "base/320193/000032019326000101/d.htm");
        assert_eq!(d["expected"]["date"], "2027-01-29");
        assert_eq!(d["expected"]["estimated"], true);
        let one = r#"{"name":"X","filings":{"recent":{"form":["8-K"],"filingDate":["2026-10-30"],"items":["2.02"],"accessionNumber":["a"],"primaryDocument":["b"]}}}"#;
        assert!(sec_earnings(one, "X", "1", "", day, 120)["expected"].is_null(), "one filing gives no cadence");
    }

    #[test]
    fn em_usd_return_math() {
        // flat 12% yield and flat FX: the monthly return is the carry, 1%
        let ys: BTreeMap<String, f64> = (1..=12).map(|m| (format!("2025-{m:02}"), 12.0)).collect();
        let fx: BTreeMap<String, f64> = (1..=12).map(|m| (format!("2025-{m:02}"), 5.0)).collect();
        let r = usd_monthly(&ys, &fx, 10.0);
        assert_eq!(r.len(), 11);
        assert!((r["2025-12"] - 0.01).abs() < 1e-12);
        assert!(annualised(&r, 11).is_some() && annualised(&r, 12).is_none(), "a missing month is null");
        // a 10% depreciation of the local currency in one month
        let mut fx2 = fx.clone();
        fx2.insert("2025-12".into(), 5.5);
        let r2 = usd_monthly(&ys, &fx2, 10.0);
        assert!((r2["2025-12"] - (1.01 * 5.0 / 5.5 - 1.0)).abs() < 1e-12);
        // duration: a 10y par bond at 5% has a modified duration of about 7.79
        assert!((par_duration(0.05, 10.0) - 7.794).abs() < 0.01);
        assert_eq!(next_month("2025-12"), "2026-01");
        assert_eq!(prev_month("2026-01"), "2025-12");
        // the index chains the newest consecutive run, 100 at its start, dated at month ends
        let mut m = BTreeMap::new();
        m.insert("2025-01".to_string(), 0.5);
        m.insert("2025-03".to_string(), 0.1);
        m.insert("2025-04".to_string(), 0.1);
        let c = chain(&m);
        assert_eq!(c.len(), 3);
        assert_eq!(c[0], ("2025-02-28".to_string(), 100.0));
        assert!((c[2].1 - 121.0).abs() < 1e-9 && c[2].0 == "2025-04-30");
    }

